const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const num=(v,lo,hi,d=0)=>{const n=Number(v);return Number.isFinite(n)?Math.min(hi,Math.max(lo,n)):d};
const today=()=>{const d=new Date();return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0")};
const phaseOf=w=>Math.min(5,Math.floor((w-1)/4));
const $=s=>document.querySelector(s);
function toast(m){const t=document.createElement("div");t.setAttribute("role","status");t.className="toast";t.textContent=m;document.body.appendChild(t);setTimeout(()=>{t.classList.add("out");setTimeout(()=>t.remove(),300)},4200)}


function migrate(s){/* preserva chaves antigas; nunca apaga */
 try{["sh_wk","sh_log2","sh_done2"].forEach(k=>{const r=localStorage.getItem(k);if(r!==null)s.legacy[k]=r});
  const wk=parseInt(s.legacy.sh_wk,10);if(wk>=1&&wk<=24)s.week=wk;
  if(s.legacy.sh_log2){const a=JSON.parse(s.legacy.sh_log2);if(Array.isArray(a))a.forEach(x=>{const b=Number(x&&(x.bpm||x.b));if(b>0)s.logs.push({t:Date.parse(x.date||x.d)||0,date:String(x.date||x.d||"").slice(0,10),ex:"legacy",exName:String(x.ex||x.name||x.n||"Registro antigo"),mins:0,bpm:b,sub:0,clean:0,total:0,q:0,tens:0,best:0,note:"Importado do plano antigo (subdivisão desconhecida)",pain:false,legacy:true})})}}catch(e){}}

function vMetro(){return `<h2>Metrônomo</h2><div class="card"><p class="big" id="mdisp"></p><div class="row" id="mdots" aria-hidden="true"></div>
 <div class="grid"><div><label for="mb">BPM do pulso</label><input id="mb" type="number" min="20" max="300" value="${window._mb||60}"></div>
 <div><label for="ms">Subdivisão</label><select id="ms">${Object.entries(SUBS).map(([k,v])=>`<option value="${k}" ${+(window._ms||1)===+k?"selected":""}>${v}</option>`).join("")}</select></div>
 <div><label for="ma">Acento</label><select id="ma"><option value="1">No 1</option><option value="24">No 2 e 4</option><option value="0">Nenhum</option></select></div></div>
 <fieldset style="border:1px solid var(--ln);margin:.6rem 0"><legend class="mu">Beats com clique</legend>${[1,2,3,4].map(i=>`<label style="display:inline-block;margin-right:1rem"><input type="checkbox" class="mbt" value="${i}" checked> ${i}</label>`).join("")}</fieldset>
 <label><input type="checkbox" id="mc"> Contagem inicial de 1 compasso</label>
 <div class="row" style="margin-top:.6rem"><button class="pri" id="mgo">Iniciar</button><button id="mtap">Tap tempo</button></div><p class="mu" id="mmsg">Se não houver som, toque em Iniciar de novo: o navegador pode bloquear áudio até um toque seu.</p></div>`}

/* ============ 7. METRÔNOMO (Web Audio, agendador com lookahead) ============ */
let M={ctx:null,run:false,timer:null,next:0,beat:0,sub:0,count:0,taps:[]};
function click(t,f,g){const o=M.ctx.createOscillator(),a=M.ctx.createGain();o.frequency.value=f;a.gain.setValueAtTime(g,t);a.gain.exponentialRampToValueAtTime(.001,t+.05);o.connect(a).connect(M.ctx.destination);o.start(t);o.stop(t+.06)}
function mUpdate(){const b=num($("#mb").value,20,300,60),s=num($("#ms").value,1,6,1);window._mb=b;window._ms=s;$("#mdisp").textContent=`♩ = ${b} × ${s} = ${b*s} notas/min`}
function sched(){const bpm=num($("#mb").value,20,300,60),sub=num($("#ms").value,1,6,1),acc=$("#ma").value,on=[...document.querySelectorAll(".mbt")].filter(c=>c.checked).map(c=>+c.value),cin=$("#mc").checked;
 while(M.next<M.ctx.currentTime+0.12){const b=M.beat%4+1,counting=M.count>0;
  if(M.sub===0){const ac=counting?b===1:(acc==="1"?b===1:acc==="24"?(b===2||b===4):false);
   if(counting||on.includes(b))click(M.next,ac?1400:900,ac?.9:.55);
   const d=Math.max(0,(M.next-M.ctx.currentTime)*1000),bb=b;setTimeout(()=>{document.querySelectorAll("#mdots .beat").forEach((e,i)=>e.classList.toggle("hit",i+1===bb))},d)}
  else if(!counting&&on.includes(b))click(M.next,600,.25);
  M.next+=60/bpm/sub;M.sub++;if(M.sub>=sub){M.sub=0;M.beat++;if(counting&&M.beat%4===0)M.count=0}}}
function mStop(){clearInterval(M.timer);M.run=false;const g=$("#mgo");if(g){g.textContent="Iniciar";g.classList.add("pri")}document.querySelectorAll("#mdots .beat").forEach(e=>e.classList.remove("hit"))}
async function mStart(){try{if(!M.ctx)M.ctx=new (window.AudioContext||window.webkitAudioContext)();if(M.ctx.state!=="running")await M.ctx.resume()}catch(e){$("#mmsg").textContent="Não foi possível iniciar o áudio neste navegador.";return}
 M.run=true;M.beat=0;M.sub=0;M.count=$("#mc").checked?1:0;M.next=M.ctx.currentTime+.08;M.timer=setInterval(sched,25);$("#mgo").textContent="Pausar";$("#mgo").classList.remove("pri")}
function bindMetro(){$("#mdots").innerHTML=[1,2,3,4].map(()=>'<span class="beat"></span>').join("");mUpdate();if(M.run){$("#mgo").textContent="Pausar";$("#mgo").classList.remove("pri")}
 ["mb","ms"].forEach(i=>$("#"+i).addEventListener("input",mUpdate));
 $("#mgo").onclick=()=>M.run?mStop():mStart();
 $("#mtap").onclick=()=>{const n=performance.now();M.taps=M.taps.filter(t=>n-t<2500);M.taps.push(n);if(M.taps.length>=2){const d=(M.taps[M.taps.length-1]-M.taps[0])/(M.taps.length-1);$("#mb").value=Math.round(num(60000/d,20,300,60));mUpdate()}}}


