function vDados(){const lg=Object.keys(S.legacy).length;return `<h2>Dados e relatório</h2><div class="g c"><p>Tudo fica só neste navegador e dispositivo (chave <code>gp_v3</code>). As chaves antigas gp_v2 e sh_* nunca são apagadas. Faça backup com frequência.</p><div class="row"><button id="bx" class="pri">Baixar backup (JSON)</button><label class="mu" style="margin:0">Importar backup <input id="bi" type="file" accept="application/json"></label></div>${S.mig.map(m=>`<p class="mu">${esc(m)}</p>`).join("")}${lg?`<p class="mu">${lg} item(ns) legados preservados.</p>`:""}</div>
 <div class="g c"><h3>Critérios de progressão (configuráveis)</h3><div class="grid">${[["clean","Limpas mínimas (0–1)",.1],["tens","Tensão máxima",1],["q","Qualidade mínima",1],["reg","Regularidade mínima",1],["sess","Dias distintos",1],["step","Passo (BPM)",1]].map(([k,n])=>`<div><label for="cf${k}">${n}</label><input id="cf${k}" data-cfg="${k}" type="number" step="${k==="clean"?.05:1}" value="${S.cfg[k]}"></div>`).join("")}</div><button id="cfr">Restaurar padrões</button></div>
 <div class="g c"><h3>Relatório para colar no Claude</h3><p class="mu">Só gera texto. Não há conexão com o Claude nem análise automática.</p><button id="rp">Gerar e copiar relatório</button><textarea id="ro" rows="10" aria-label="Relatório" style="margin-top:.5rem"></textarea></div>
 <div class="g c"><h3>Autoteste do motor adaptativo</h3><p class="mu">Roda 4 perfis simulados, dor, subdivisões e sessões de 60/90 min. Não altera seus dados.</p><button id="st">Rodar autoteste</button><pre id="so"></pre></div><div class="g c"><button id="wp">Apagar dados deste plano</button></div>`}
function report(){const o=po(),P=prio(S.logs,o.now),L=[...S.logs].sort((a,b)=>b.t-a.t).filter(l=>!l.legacy);let t=`RELATÓRIO — guitarra (24 semanas)\nSemana ${S.week}, fase ${o.ph+1}. Gerado em ${today()}. Dados informados por mim, sem medição automática.\n\nDOMÍNIO:\n`;
 Object.keys(SK).forEach(k=>{const s=P.st[k];t+=`- ${SK[k]}: ${s?lvl(s.sc)+(s.stag?" (estagnada)":"")+(s.ret?" (retenção?)":""):"não medida"}\n`});
 t+="\nÚLTIMAS SESSÕES:\n"+(L.slice(0,10).map(l=>`${l.date} | ${nameOf(l.ex)} | ${l.bpm} BPM × ${l.sub} | ${l.clean}/${l.total} | q${l.q} reg${l.reg||"-"} | tensão ${l.tens}${l.pain?" | DOR":""}`).join("\n")||"(sem registros)");return t+"\n\nPeço: apontar o gargalo principal e um ajuste para a próxima semana, separando dado medido de hipótese."}

