 if(d.p){if(d.p==="play")AU.paused?AU.play():AU.pause();if(d.p==="a")AB.a=AU.currentTime;if(d.p==="b")AB.b=AU.currentTime;if(d.p==="clr")AB.a=AB.b=null;if(d.p==="a"||d.p==="b"||d.p==="clr")show("rep");return}
 if(d.ab&&sc){if(AB.a==null||AB.b==null||AB.b<=AB.a){toast("Marque A e depois B (B depois de A).");return}sc.a=AB.a;sc.b=AB.b;save();show("rep");return}
